CREATE TABLE public.months(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,year integer,month integer,half integer,income numeric,saved numeric, UNIQUE(year,month,half));
CREATE TABLE public.entries(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,month_id bigint REFERENCES public.months(id),type text,category text,name text,planned numeric,actual numeric);
CREATE TABLE public.backlog(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,category text,name text,planned numeric);
INSERT INTO public.months VALUES (41,2026,11,1,10000.25,1000.25);
INSERT INTO public.entries VALUES (51,41,'mandatory','shared','Непредвиденные',500.50,20.25), (52,41,'planned','personal','Еда',2000,2100);
INSERT INTO public.backlog VALUES (61,'shared','Покупка',123.45);
GRANT ALL ON public.months,public.entries,public.backlog TO authenticated;
ALTER TABLE public.months ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.entries ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.backlog ENABLE ROW LEVEL SECURITY;
CREATE POLICY auth_full_access ON public.months FOR ALL TO authenticated USING(true) WITH CHECK(true);
CREATE POLICY auth_full_access ON public.entries FOR ALL TO authenticated USING(true) WITH CHECK(true);
CREATE POLICY auth_full_access ON public.backlog FOR ALL TO authenticated USING(true) WITH CHECK(true);
